WITH transactions_by_account AS (SELECT account_id, COUNT(CASE WHEN txn_type = 'REFUND' THEN 1 END) AS refund_count, ROUND((100 * SUM(CASE WHEN txn_type = 'CREDIT' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_credit FROM transactions WHERE merchant IS NOT NULL GROUP BY account_id) SELECT a.id, a.customer_id, tba.refund_count, tba.pct_credit FROM accounts a LEFT JOIN transactions_by_account tba ON a.id = tba.account_id WHERE tba.pct_credit > 43 ORDER BY a.id DESC
